DO $fix$ DECLARE s text; BEGIN SELECT pg_get_functiondef('public.reservar_estoque_item(uuid,numeric,uuid,text,uuid,uuid,uuid,text)'::regprocedure) INTO s; IF position($q$v_parent_ctx->'reserve_args' IS DISTINCT FROM jsonb_build_object$q$ IN s)=0 THEN RAISE EXCEPTION 'STOCK_RESERVE_ARGS_BASELINE_CHANGED'; END IF; s:=replace(s,$q$v_parent_ctx->'reserve_args' IS DISTINCT FROM jsonb_build_object('os_id',p_os_id::text,'os_tipo',p_os_tipo,'cliente_id',p_cliente_id::text,'partner_id',p_partner_id::text,'partner_order_id',p_partner_order_id::text,'observacao',p_observacao)$q$,$q$v_parent_ctx->'reserve_args' IS DISTINCT FROM jsonb_strip_nulls(jsonb_build_object('os_id',p_os_id::text,'os_tipo',p_os_tipo,'cliente_id',p_cliente_id::text,'partner_id',p_partner_id::text,'partner_order_id',p_partner_order_id::text,'observacao',p_observacao))$q$); EXECUTE s; END $fix$;